<template>
	<div class="flex h-dvh flex-col overflow-hidden bg-ui-surface-gray-50 text-xs">
		<!-- ============ HEADER ============ -->
		<div
			class="mb-4 flex shrink-0 items-center justify-between gap-2 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex min-w-0 items-center gap-1.5">
				<RouterLink
					:to="{ name: 'Home' }"
					class="-ml-2 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali ke Home"
					aria-label="Kembali ke Home"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<h1 class="truncate !text-xl font-semibold text-ui-ink-gray-900">Tebus Motor Nasabah</h1>
			</div>
		</div>

		<!-- ============ LIST ============ -->
		<div class="app-container min-h-0 flex-1 overflow-y-auto px-4 md:px-6 pb-safe">
			<div v-if="loading && !rows.length" class="flex justify-center pt-10">
				<svg
					class="h-6 w-6 animate-spin text-primary"
					viewBox="0 0 24 24"
					fill="none"
					xmlns="http://www.w3.org/2000/svg"
				>
					<circle
						cx="12"
						cy="12"
						r="9"
						stroke="currentColor"
						stroke-width="2"
						stroke-opacity="0.25"
					/>
					<path
						d="M21 12a9 9 0 0 0-9-9"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
					/>
				</svg>
			</div>

			<pre v-else-if="error" class="whitespace-pre-wrap text-sm text-ui-ink-red-600">{{
				error
			}}</pre>

			<div v-else-if="!rows.length" class="px-6 pt-16 text-center">
				<p class="text-sm text-ui-ink-gray-500">Tidak ada data.</p>
			</div>

			<!-- ====== LIST CARD ====== -->
			<div v-else class="card-grid pb-2">
				<div
					v-for="row in rows"
					:key="row.name"
					role="button"
					tabindex="0"
					class="cursor-pointer rounded-xl border border-ui-line-gray-200 bg-ui-surface p-4 shadow-sm active:bg-ui-surface-gray-50"
					@click="goToDetail(row.name)"
					@keyup.enter="goToDetail(row.name)"
				>
					<!-- Baris atas: nomor + panah -->
					<div class="flex items-start justify-between gap-2">
						<p class="min-w-0 truncate text-sm font-bold text-ui-ink-gray-900">
							{{ row.name }}
						</p>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-5 w-5 shrink-0 text-primary"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M5 12h14" />
							<path d="m12 5 7 7-7 7" />
						</svg>
					</div>

					<!-- Tanggal tebus -->
					<p class="mt-0.5 text-xs text-ui-ink-gray-400">
						{{ row.tanggal_tebus ? formatDate(row.tanggal_tebus) : '—' }}
					</p>

					<!-- Nama nasabah + status pill -->
					<div class="mt-3 flex items-center justify-between gap-2">
						<span class="truncate text-sm font-normal text-ui-ink-gray-800">
							{{ row.nama_nasabah || '—' }}
						</span>
						<span
							class="flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium"
							:class="tebusPillClass(row.workflow_state)"
						>
							<span class="h-1.5 w-1.5 rounded-full bg-current" />
							{{ row.workflow_state || '—' }}
						</span>
					</div>

					<div class="my-3 border-t border-ui-line-gray-100" />

					<!-- Nopol / Motor Tarikan | Admin Tebus -->
					<div class="flex items-end justify-between gap-3">
						<div class="min-w-0">
							<p class="text-xs text-ui-ink-gray-400">Nopol</p>
							<p class="mt-0.5 truncate text-sm font-semibold text-primary">
								{{ row.nopol || row.motor_tarikan || '—' }}
							</p>
						</div>
						<div class="shrink-0 text-right">
							<p class="text-xs text-ui-ink-gray-400">Admin Tebus</p>
							<p class="mt-0.5 text-sm font-bold text-ui-ink-gray-900">
								{{ formatMoney(row.nominal_tebus) }}
							</p>
						</div>
					</div>
				</div>
			</div>

			<div v-if="rows.length && hasMore" class="p-3 text-center">
				<button
					type="button"
					:disabled="loading"
					class="appearance-none text-sm font-medium text-primary disabled:opacity-50"
					@click="loadMore"
				>
					{{ loading ? 'Memuat…' : 'Muat lebih banyak' }}
				</button>
			</div>
		</div>

		<!-- ---- FAB tambah Tebus Motor Nasabah (bulat, kanan-bawah) ---- -->
		<button
			type="button"
			class="fixed fab-safe right-5 z-40 flex h-14 w-14 items-center justify-center rounded-full bg-primary text-ui-onPrimary shadow-lg transition hover:bg-primary/90 active:scale-95"
			title="Tambah Tebus Motor Nasabah"
			aria-label="Tambah Tebus Motor Nasabah"
			@click="onCreate"
		>
			<svg
				xmlns="http://www.w3.org/2000/svg"
				viewBox="0 0 24 24"
				class="h-7 w-7"
				fill="none"
				stroke="currentColor"
				stroke-width="2.2"
				stroke-linecap="round"
				stroke-linejoin="round"
			>
				<path d="M12 5v14" />
				<path d="M5 12h14" />
			</svg>
		</button>
	</div>
</template>

<script setup>
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { tebusPillClass } from '../data/tebusMotorStatus'

const router = useRouter()

function goToDetail(name) {
	router.push({ name: 'TebusMotorDetail', params: { name } })
}
function onCreate() {
	router.push({ name: 'TebusMotorCreate' })
}

const FIELDS = [
	'name',
	'tanggal_tebus',
	'motor_tarikan',
	'no_perjanjian',
	'nama_nasabah',
	'nopol',
	'nominal_tebus',
	'workflow_state',
	'modified',
]

const pageLength = 20
const start = ref(0)
const rows = ref([])
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

const list = createResource({
	url: 'frappe.client.get_list',
	makeParams() {
		return {
			doctype: 'Tebus Motor Nasabah',
			fields: JSON.stringify(FIELDS),
			order_by: 'modified desc',
			limit_start: start.value,
			limit_page_length: pageLength,
		}
	},
	auto: false,
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === pageLength
		loading.value = false
	},
	onError(err) {
		error.value = err?.message || String(err)
		loading.value = false
	},
})

function loadMore() {
	start.value += pageLength
	loading.value = true
	list.fetch()
}

function formatDate(v) {
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
}
function formatMoney(v) {
	if (v == null || v === '') return '—'
	const n = Number(v)
	if (Number.isNaN(n)) return String(v)
	return `Rp ${new Intl.NumberFormat('id-ID').format(n)}`
}

onMounted(async () => {
	await refreshCsrfToken()
	loading.value = true
	list.fetch()
})
</script>
